import importlib
for mod in ['lxml', 'defusedxml', 'xml.dom.minidom', 'xml.etree.ElementTree']:
    try:
        importlib.import_module(mod)
        print(f"OK: {mod}")
    except Exception as e:
        print(f"MISSING: {mod} -> {e}")

from defusedxml.minidom import parse
import os

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

def q(tag):
    return f'{{{W}}}{tag}'

doc = parse(os.path.join('unpacked', 'word', 'document.xml'))

for p in doc.getElementsByTagName(q('p')):
    style = ''
    pPr = p.getElementsByTagName(q('pPr'))
    if pPr:
        ps = pPr[0].getElementsByTagName(q('pStyle'))
        if ps:
            style = ps[0].getAttribute(q('val'))
    texts = []
    for t in p.getElementsByTagName(q('t')):
        if t.firstChild:
            texts.append(t.firstChild.nodeValue)
    text = ''.join(texts)
    print(f"STYLE={style!r} TEXT={text!r}")

